namespace sv_820a2dfc138c4a3db9510e23527ae148.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_820a2dfc138c4a3db9510e23527ae148.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-4">Product Catalog</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}
else
{
    <div class="catalog-layout d-flex gap-4">
        @* ───── Left Sidebar (Filters) ───── *@
        <aside class="catalog-sidebar">
            <h5>Filters</h5>

            <div class="mb-3">
                <label class="form-label fw-semibold">Category</label>
                @if (_categories is null)
                {
                    <p class="text-muted small">Loading…</p>
                }
                else
                {
                    @foreach (var cat in _categories)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                                   checked="@(_selectedCategories.Contains(cat))"
                                   @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                            <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                        </div>
                    }
                }
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Price Range</label>
                <div class="d-flex gap-2 align-items-center">
                    <input type="number" class="form-control form-control-sm" placeholder="Min"
                           @bind="_minPrice" @bind:event="oninput" min="0" />
                    <span>–</span>
                    <input type="number" class="form-control form-control-sm" placeholder="Max"
                           @bind="_maxPrice" @bind:event="oninput" min="0" />
                </div>
            </div>

            <div class="form-check mb-3">
                <input class="form-check-input" type="checkbox" id="inStockOnly"
                       @bind="_inStockOnly" />
                <label class="form-check-label" for="inStockOnly">In Stock Only</label>
            </div>

            <div class="d-grid gap-2">
                <button class="btn btn-primary btn-sm" @onclick="ApplyFiltersAsync">Apply Filters</button>
                <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFiltersAsync">Clear Filters</button>
            </div>
        </aside>

        @* ───── Main Content ───── *@
        <section class="catalog-main flex-grow-1">
            @* Toolbar *@
            <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                <div class="d-flex align-items-center gap-2">
                    <label class="form-label mb-0 fw-semibold" for="sortSelect">Sort:</label>
                    <select id="sortSelect" class="form-select form-select-sm w-auto"
                            @bind="_sortBy" @bind:after="OnSortChangedAsync">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A–Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>

                @if (_result is not null && _result.TotalCount > 0)
                {
                    var first = (_result.Page - 1) * _result.PageSize + 1;
                    var last = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
                    <span class="text-muted small">Showing @first–@last of @_result.TotalCount products</span>
                }
            </div>

            @* Product Grid / States *@
            @if (_loading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading…</span>
                    </div>
                    <p class="mt-2 text-muted">Loading products…</p>
                </div>
            }
            else if (_result is null || _result.Items.Count == 0)
            {
                <div class="text-center py-5">
                    <p class="text-muted fs-5">No products found.</p>
                    <button class="btn btn-outline-primary btn-sm" @onclick="ClearFiltersAsync">Clear Filters</button>
                </div>
            }
            else
            {
                <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3">
                    @foreach (var product in _result.Items)
                    {
                        <div class="col">
                            <ProductCard Product="product"
                                         OnProductSelected="OnProductSelected"
                                         OnAddToCart="OnAddToCart" />
                        </div>
                    }
                </div>

                @* Pagination *@
                @if (TotalPages > 1)
                {
                    <nav aria-label="Product pagination" class="mt-4">
                        <ul class="pagination justify-content-center flex-wrap">
                            <li class="page-item @(_currentPage == 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(_currentPage - 1)"
                                        disabled="@(_currentPage == 1)">Previous</button>
                            </li>
                            @for (var p = 1; p <= TotalPages; p++)
                            {
                                var pageNum = p;
                                <li class="page-item @(pageNum == _currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="() => GoToPageAsync(pageNum)">@pageNum</button>
                                </li>
                            }
                            <li class="page-item @(_currentPage == TotalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(_currentPage + 1)"
                                        disabled="@(_currentPage == TotalPages)">Next</button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        </section>
    </div>
}

@code {
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }
    [Parameter] public EventCallback<Product> OnAddToCart { get; set; }

    private const int PageSize = 12;

    // Filter state
    private List<string>? _categories;
    private HashSet<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    // Search state
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private PagedResult<Product>? _result;
    private bool _loading = true;
    private string? _error;

    private int TotalPages => _result is null || _result.PageSize == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var searchTask = SearchProductsAsync();
            await Task.WhenAll(categoriesTask, searchTask);
            _categories = await categoriesTask;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
            _loading = false;
        }
    }

    private async Task SearchProductsAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            var filter = new ProductFilter(
                Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
                MinPrice: _minPrice,
                MaxPrice: _maxPrice,
                InStockOnly: _inStockOnly
            );

            _result = await ProductService.SearchAsync(filter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            _selectedCategories.Add(category);
        else
            _selectedCategories.Remove(category);
    }

    private async Task ApplyFiltersAsync()
    {
        _currentPage = 1;
        await SearchProductsAsync();
    }

    private async Task ClearFiltersAsync()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        _currentPage = 1;
        _sortBy = "price_asc";
        await SearchProductsAsync();
    }

    private async Task OnSortChangedAsync()
    {
        _currentPage = 1;
        await SearchProductsAsync();
    }

    private async Task GoToPageAsync(int page)
    {
        if (page < 1 || page > TotalPages) return;
        _currentPage = page;
        await SearchProductsAsync();
    }

    private async Task RetryAsync()
    {
        _error = null;
        _loading = true;

        try
        {
            _categories ??= await ProductService.GetCategoriesAsync();
            await SearchProductsAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
            _loading = false;
        }
    }
}

.catalog-sidebar {
    min-width: 240px;
    max-width: 25%;
    flex: 0 0 25%;
    padding: 1rem;
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 0.375rem;
    align-self: flex-start;
}

.catalog-main {
    min-width: 0;
}

.product-card {
    cursor: pointer;
    transition: box-shadow 0.15s ease-in-out, transform 0.15s ease-in-out;
    height: 100%;
}

.product-card:hover {
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.12);
    transform: translateY(-2px);
}

.product-image-placeholder {
    background-color: var(--bs-secondary-bg, #e9ecef);
    height: 180px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--bs-secondary-color, #6c757d);
    font-size: 0.875rem;
    border-radius: 0.375rem 0.375rem 0 0;
}

.star-rating {
    color: #ffc107;
    letter-spacing: 1px;
}

@using sv_820a2dfc138c4a3db9510e23527ae148.Services

<div class="card product-card" @onclick="HandleCardClick">
    <div class="product-image-placeholder" title="@Product.Name">
        @Product.Name
    </div>
    <div class="card-body d-flex flex-column">
        <h6 class="card-title mb-1">@Product.Name</h6>
        <p class="card-text fw-bold text-primary mb-1">@Product.Price.ToString("C")</p>
        <div class="star-rating mb-2" aria-label="@($"Rating: {Product.Rating:F1} out of 5")">
            @RenderStars(Product.Rating)
        </div>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2 align-self-start">Out of Stock</span>
        }
        <button class="btn btn-sm btn-success mt-auto"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Product Product { get; set; } = default!;
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }
    [Parameter] public EventCallback<Product> OnAddToCart { get; set; }

    private static string RenderStars(double rating)
    {
        var fullStars = (int)Math.Round(rating);
        var emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }

    private async Task HandleCardClick()
    {
        if (OnProductSelected.HasDelegate)
            await OnProductSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        if (OnAddToCart.HasDelegate)
            await OnAddToCart.InvokeAsync(Product);
    }
}

